	setA := make(map[int]bool)
	for _, d := range digitsA {
		val, _ := fmt.Sscanf(d, "%d")
		setA[val] = true
	}

	setB := make(map[int]bool)
	for _, d := range digitsB {
		val, _ := fmt.Sscanf(d, "%d")
		setB[val] = true
	}

	// Check for common digits (single digit pretty number)
	common := []int{}
	for i := 1; i <= 9; i++ {
		if setA[i] && setB[i] {
			common = append(common, i)
		}
	}

	if len(common) > 0 {
		sort.Ints(common)
		fmt.Fprintln(writer, common[0])
		return
